DEFAULT_GLYPH_COLOR = P["lantern-gold"]
LIGHT_FALLBACK = "#e8e4f5"


def _luminance(hex_color: str) -> float:
    h = hex_color.lstrip("#")
    chans = []
    for i in (0, 2, 4):
        c = int(h[i : i + 2], 16) / 255
        chans.append(c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4)
    return 0.2126 * chans[0] + 0.7152 * chans[1] + 0.0722 * chans[2]


def on_dark(hex_color: str) -> str:
    """Brand colour as-is, or a light fallback when it would vanish on the night sky."""
    return LIGHT_FALLBACK if _luminance(hex_color) < 0.08 else hex_color


def icon(name: str, x: float, y: float, size: float, color: str | None = None) -> str:
    """A <g transform><path/></g> fragment for a brand or glyph icon (24x24 source)."""
    if name in BRAND:
        d, hx = BRAND[name]
        fill = color or on_dark(hx)
        rule = ""
    elif name in GLYPH:
        d = GLYPH[name]
        fill = color or DEFAULT_GLYPH_COLOR
        rule = ' fill-rule="evenodd"'
    else:
        raise KeyError(name)
    s = size / 24
    return (
        f'<g transform="translate({_num(x)},{_num(y)}) scale({_num(s)})">'
        f'<path d="{d}" fill="{fill}"{rule}/></g>'
    )
